computed.isAudioVideo:
isAudioVideo() {
                    switch (this.document.mime_type) {
                        case "video/mp4":
                        case "audio/wave":
                        case "audio/wav":
                        case "audio/x-wav":
                        case "audio/x-pn-wav":
                        case "audio/webm":
                        case "video/webm":
                        case "audio/ogg":
                        case "video/ogg":
                        case "application/ogg":
                            return true;
                            break;
                        default:
                            return false;
                    }
                }

computed.isDrive:
isDrive() {
                    // removine onedrive from this list as it is to be displayed normally
                    let drives = ['google', 'dropbox', 'onedrive'];
                    if (this.isAttachment) {
                        return drives.includes(this.document.attached_type);
                    } else if (this.isAgendaUpload) {
                        return drives.includes(this.document.type);
                    } else {
                        return drives.includes(this.document.upload_type);
                    }
                }

