computed.pdfIsConverting:
pdfIsConverting() {
                    if (this.document.pdf)
                        return this.document.pdf.status === 'processing';

                    if (this.document.is_convertable && ! this.document.pdf)
                        return true;

                    return this.document.pdf && this.document.pdf.status === 'processing';
                }

methods.downloadClicked:
downloadClicked() {
                    let format = $("#select-format").val();
                    if (format === "original") {
                        $("#download-original-file")[0].click();
                    } else {
                        logDownload('downloaded (pdf)', (this.downloadWithPublic || this.downloadWithPrivate) ? 'With Annotations' : null);
                        if (this.isOnedrive && this.document.display_options === 'LIVE') { // can't have annotations with live files
                            let filename = this.document.title ?? this.document.attached_name;
                            if (this.getFileExtension(filename) !== 'pdf') {
                                filename += ".pdf";
                            }
                            window.location = (Boardable.org_url + "pdfs/download/" + this.document.pdf.id + "/" + filename);
                        }
                        else if (this.downloadWithPublic || this.downloadWithPrivate) {
                            document_app.$refs.viewer.downloadWithAnnotations(this.downloadWithPublic, this.downloadWithPrivate);
                        } else {
                            document_app.$refs.viewer.downloadNoAnnotations();
                        }
                    }

                    $("#download-button").dropdown("toggle");
                }

methods.fileSize:
fileSize(bytes, decimals = 2) {
                    if (bytes === 0) return "0 Bytes";

                    const k = 1024;
                    const dm = decimals < 0 ? 0 : decimals;
                    const sizes = ["Bytes", "KB", "MB", "GB", "TB", "PB", "EB", "ZB", "YB"];

                    const i = Math.floor(Math.log(bytes) / Math.log(k));

                    return parseFloat((bytes / Math.pow(k, i)).toFixed(dm)) + " " + sizes[i];
                }

