methods.saveEditedDocumentTitle:
saveEditedDocumentTitle() {
                    this.editTitleLoading = true;
                    this.editTitleErrors = [];
                    axios.post(`${Boardable.org_url}documents/${this.document.id}`, {
                            title: this.editableDocumentTitle,
                        })
                        .then((response) => {
                            let document = response.data;
                            this.document.title = document.title;
                            this.editingTitle = false;
                        })
                        .catch((error) => {
                            this.editTitleErrors = error.response.data.errors;
                        })
                        .finally(() => {
                            this.editTitleLoading = false;
                        });
                }

methods.toggleEditingDocumentTitle:
toggleEditingDocumentTitle() {
                    this.editableDocumentTitle = this.document.title;
                    this.editingTitle = !this.editingTitle;
                    if(this.editingTitle) {
                        this.$nextTick(() => {
                            this.$refs['edit_title_input']?.focus();
                        });
                    }
                }

methods.onReplacementFileSelected:
onReplacementFileSelected(event) {
                    const file = event.target.files[0]
                    if (file) {
                        this.document_filename = file.name;
                        this.show_annotations_warning = true
                    }
                }

methods.reset:
reset() {
                    this.form = {
                        title: null,
                        body: null,
                        disable_downloads: false,
                        file: null
                    };
                    this.document_filename = null;
                    this.show_annotations_warning = false;
                    clearEditorContent("#edit-document-editor");
                }

methods.save:
save() {
                    this.submitting = true;
                    this.errors = [];
                    const formData = new FormData();
                    formData.append('body', tinymce.get("edit-document-editor").getContent());
                    formData.append('title', this.form.title);
                    formData.append('disable_downloads', this.form.disable_downloads);
                    formData.append('upload_type', this.upload_type);
                    formData.append('document_id', this.form.id);
                    formData.append('file', $("#replace-file-input")[0]?.files[0]);
                    axios.post('https://app.boardable.com/quorumrelay-evaluation/documents/' + this.form.id, formData, {
                            headers: {
                                "Content-Type": "multipart/form-data"
                            }
                        }
                    )
                    .then((response) => {
                        $("#edit-document").modal("hide");
                        formStatus.success();
                        if (typeof documentsApp !== "undefined")
                            documentsApp.reloadFolder();
                        else if (typeof document_app !== "undefined")
                            document_app.reloadPage();
                    })
                    .catch((error) => {
                        console.log(error);
                        this.errors = error.response.data.errors;
                    })
                    .finally(() => {
                        this.submitting = false;
                    });
                }

methods.setFormData:
setFormData(document_data) {
                    let form_data = this.form;
                    form_data.id = document_data.id;
                    form_data.title = document_data.title;
                    form_data.body = document_data.body;
                    form_data.disable_downloads = !!document_data.disable_downloads;
                    this.upload_type = document_data.upload_type;
                    this.document_filename = document_data.filename;
                    tinymce.get("edit-document-editor").setContent(document_data.body);
                }
